# Three Dell Technologies Info Hub posts: MI355X (v6.0), overview (v6.1), YOLO (v6.0). Reads raw/inf_6.0.json and raw/inf_6.1.json. python3 -I check_claims_dell_posts.py
import json,hashlib
R0=open('raw/inf_6.0.json','rb').read(); R1=open('raw/inf_6.1.json','rb').read()
A=json.loads(R0); B=list(json.loads(R1).values())
def a(i,m,s):
    r=[x for x in A if x['ID']==i and x['Model']==m and x['Scenario']==s and x['Category']=='closed']; assert len(r)==1,(i,m,s,len(r)); return r[0]['Performance_Result']
def b(org,sysn,m,s):
    r=[x for x in B if x['Organization']==org and sysn in x['SystemName'] and x['Model']==m and x['Scenario'].lower()==s.lower() and x['Division']=='closed']; assert len(r)==1,(org,sysn,m,s,len(r)); return r[0]['Result']
def mk(i,q,calc,st,got,out,note): return dict(id=i,quote=q,calc=calc,stated=st,delivered=got,outcome=out,note=note,label_mismatch=False)
pc=lambda x,y:100*(x/y-1)
# ---- post 1, MI355X v6.0
M=[]
M.append(mk('M1','achieving 70,610.8 tokens/s','entry 6.0-0020 (Dell XE9785L, 8 x MI355X), Llama 2 70B Interactive','70,610.8 tokens/s',f'{a("6.0-0020","llama2-70b-99","Interactive"):,.1f} tokens/s','CONSISTENT' if abs(a("6.0-0020","llama2-70b-99","Interactive")-70610.8)<0.05 else 'ABOVE',''))
o=a('6.0-0020','llama2-70b-99','Offline')/a('6.0-0019','llama2-70b-99','Offline'); s=a('6.0-0020','llama2-70b-99','Server')/a('6.0-0019','llama2-70b-99','Server')
M.append(mk('M2','The MI355X delivers nearly 4x higher inference performance compared to the MI300X.','entry 6.0-0020 (8 x MI355X) against entry 6.0-0019 (Dell XE9680, 8 x MI300X), Llama 2 70B','nearly 4x',f'Offline {o:.2f}x, Server {s:.2f}x. Entry 6.0-0019 has no Interactive row','CONSISTENT' if 3.6<=o<=4.05 and 3.6<=s<=4.05 else 'BELOW','The post says three scenarios. The file has two for the MI300X entry.'))
M.append(mk('M3','Table 1: GPT-OSS-120B Performance on XE9785L_8xMI355X. Server 78,603.5 queries/s. Offline 91,395.5 samples/s.','entry 6.0-0020 GPT-OSS-120B','Server 78,603.5, Offline 91,395.5',f'Server {a("6.0-0020","gpt-oss-120b","Server"):,.1f} tokens/s, Offline {a("6.0-0020","gpt-oss-120b","Offline"):,.1f} tokens/s','CONSISTENT' if abs(a("6.0-0020","gpt-oss-120b","Server")-78603.5)<0.05 and abs(a("6.0-0020","gpt-oss-120b","Offline")-91395.5)<0.05 else 'ABOVE','The values match. The post labels the units queries/s and samples/s. The file lists tokens/s for both.'))
gp=sorted({x['Submitter'] for x in A if x['Model']=='gpt-oss-120b' and x['Category']=='closed'})
M.append(mk('M4','The XE9785L (8x MI355X) also delivered the first MLPerf submission of the open-source GPT-OSS-120B model','closed GPT-OSS-120B entries in v6.0',"first submission of GPT-OSS-120B",f'{len(gp)} submitters list GPT-OSS-120B in v6.0: '+', '.join(gp),'CANNOT_TELL','v6.0 is the first round with this model. The file does not order submissions within the round.'))
mb=[a('6.0-0069','llama2-70b-99','Offline'),a('6.0-0070','llama2-70b-99','Offline'),a('6.0-0032','llama2-70b-99','Offline')]; ms=[a('6.0-0069','llama2-70b-99','Server'),a('6.0-0070','llama2-70b-99','Server'),a('6.0-0032','llama2-70b-99','Server')]
eo=100*a('6.0-0031','llama2-70b-99','Offline')/sum(mb); es=100*a('6.0-0031','llama2-70b-99','Server')/sum(ms)
M.append(mk('M5','Approximately 95.5% scaling efficiency was achieved, despite mixing GPU generations across continents.','entry 6.0-0031 (Dell MangoBoost heterogeneous cluster, 24 GPUs) against the sum of single-system entries 6.0-0069 (8 x MI300X), 6.0-0070 (8 x MI325X) and 6.0-0032 (8 x MI355X), Llama 2 70B','about 95.5%',f'Offline {a("6.0-0031","llama2-70b-99","Offline"):,.0f} against a sum of {sum(mb):,.0f} = {eo:.1f}%. Server {a("6.0-0031","llama2-70b-99","Server"):,.0f} against {sum(ms):,.0f} = {es:.1f}%','CONSISTENT' if abs(eo-95.5)<0.1 else 'BELOW','The post does not name its baseline. The Offline figure reproduces with these three entries. Server is lower. The regions are not in the file.'))
r=[pc(a('6.0-0033','llama2-70b-99',sc),a('6.0-0032','llama2-70b-99',sc)) for sc in ('Offline','Server')]
M.append(mk('M6','Only ~16-18% throughput reduction for a 29% power drop','entry 6.0-0033 (XE9785, MI355X power capped at 1000 W) against entry 6.0-0032 (same system, 1400 W), Llama 2 70B','16% to 18% lower',f'Offline {r[0]:+.1f}%, Server {r[1]:+.1f}%. 1,000 W against 1,400 W is {pc(1000,1400):+.1f}%','CONSISTENT' if abs(r[0]+16)<0.5 and abs(r[1]+18)<0.5 else 'BELOW',''))
pw=[(1+r[i]/100)/(1000/1400) for i in range(2)]
M.append(mk('M7','17.5% better tokens/s per Watt efficiency at the 1000W cap','same two entries, throughput divided by the capped power (1,000 W against 1,400 W)','+17.5%',f'Offline {100*(pw[0]-1):+.1f}%, Server {100*(pw[1]-1):+.1f}% using the cap values. Neither entry has measured power','CANNOT_TELL','The cap values are not measured power. The Offline figure reproduces from them and the Server figure does not.'))
# ---- post 2, overview v6.1
O=[]
xl=lambda m,s:b('Dell','XE9785L_8xMI355X',m,s)
O.append(mk('O1','The XE9785L produced 103,932 tokens/s on Llama2 70B at 99.9% Server and 110,188 tokens/s on GPT-OSS-120B Server','v6.1 Dell XE9785L_8xMI355X, Llama 2 70B 99.9 Server and GPT-OSS-120B Server','103,932 and 110,188',f'{xl("llama2-70b-99.9","Server"):,.0f} and {xl("gpt-oss-120b","Server"):,.0f}','CONSISTENT' if round(xl("llama2-70b-99.9","Server"))==103932 and round(xl("gpt-oss-120b","Server"))==110188 else 'ABOVE',''))
mi=sorted({x['Organization'] for x in B if 'MI350P' in str(x.get('accelerator_model_name'))+str(x.get('SystemName'))})
O.append(mk('O2','As the only MLPerf Inference v6.1 submission featuring the AMD Instinct(TM) MI350P','every v6.1 row whose accelerator is MI350P','only submission with MI350P','Submitters with MI350P: '+', '.join(mi),'CONSISTENT' if mi==['Dell_AMD'] else 'BELOW','The submitter name in the file is Dell_AMD.'))
g=[x for x in B if 'XE9712' in x['SystemName'] and x['Division']=='closed'][0]
O.append(mk('O3','Dell demonstrated the massive scale of NVDIA GB300 infrastructure with 72 GB300 288GB GPUs spanning 18 PowerEdge XE9712 nodes.','v6.1 Dell PowerEdge XE9712 entry','72 GPUs, 18 nodes',f'{g["total_accelerators"]} accelerators, {g["number_of_nodes"]} nodes, {g["accelerator_model_name"]}','CONSISTENT' if g['total_accelerators']==72 and g['number_of_nodes']==18 else 'BELOW',''))
O.append(mk('O4','delivering 10.585 seconds of SingleStream latency and 0.646 seconds Offline performance on WAN 2.2 T2V A14B.','v6.1 Dell XE9712 WAN 2.2 SingleStream and Offline','10.585 s and 0.646 s',f'SingleStream {b("Dell","XE9712","wan-2.2-t2v-a14b","SingleStream"):.3f} s. Offline {b("Dell","XE9712","wan-2.2-t2v-a14b","Offline"):.4f} samples/s','CONSISTENT' if abs(b("Dell","XE9712","wan-2.2-t2v-a14b","SingleStream")-10.585)<0.001 and abs(b("Dell","XE9712","wan-2.2-t2v-a14b","Offline")-0.646)<0.001 else 'ABOVE','Both values match. The file lists Offline in samples per second. The post writes seconds.'))
O.append(mk('O5','the XE9785L B300 configuration achieved 113,101 tokens/s on Llama 2 70B Offline','v6.1 Dell XE9785L (8 x B300) Llama 2 70B 99.9 Offline','113,101',f'{b("Dell","XE9785L (8x B300","llama2-70b-99.9","Offline"):,.0f}','CONSISTENT' if round(b("Dell","XE9785L (8x B300","llama2-70b-99.9","Offline"))==113101 else 'ABOVE',''))
dk=[x for x in B if x['Organization'].startswith('Dell') and x['Model']=='deepseek-r1']
O.append(mk('O6','70,494 tokens/s on DeepSeek-R1 Offline','every v6.1 DeepSeek-R1 row from a Dell submitter','70,494 tokens/s Offline',f'{len(dk)} DeepSeek-R1 rows from Dell, Dell_AMD or Dell_MangoBoost in the v6.1 file','CANNOT_TELL','The file has no Dell DeepSeek-R1 row to compare with.'))
O.append(mk('O7','reaching 28,973 tokens/s in Server and 29,797 tokens/s in Offline','v6.1 Dell XE7740 (8 x RTX PRO 6000) Llama 2 70B 99.9','28,973 and 29,797',f'{b("Dell","XE7740","llama2-70b-99.9","Server"):,.1f} and {b("Dell","XE7740","llama2-70b-99.9","Offline"):,.1f}','CONSISTENT' if round(b("Dell","XE7740","llama2-70b-99.9","Server"))==28973 and round(b("Dell","XE7740","llama2-70b-99.9","Offline"))==29797 else 'ABOVE',''))
us=pc(b('Dell','XE7740','llama2-70b-99.9','Server'),a('6.0-0022','llama2-70b-99.9','Server')); uo=pc(b('Dell','XE7740','llama2-70b-99.9','Offline'),a('6.0-0022','llama2-70b-99.9','Offline'))
O.append(mk('O8','highlighting the 13.5% and 10.2% improvement in the Server and Offline scenarios respectively for the Llama 2 70B model','Dell XE7740 v6.0 entry 6.0-0022 against the v6.1 entry, Llama 2 70B 99.9','+13.5% Server, +10.2% Offline',f'Server {us:+.1f}%, Offline {uo:+.1f}%','CONSISTENT' if abs(us-13.5)<0.06 and abs(uo-10.2)<0.06 else 'ABOVE','The v6.0 XE7745 entry 6.0-0023 gives +13.5% Server and +11.1% Offline.'))
hc=[x for x in B if x['Organization']=='Dell_MangoBoost' and 'Four-Cluster' in x['SystemName']][0]
O.append(mk('O9',"Dell's v6.1 submission demonstrates this concept with a 32-GPU heterogeneous four-cluster configuration combining AMD Instinct(TM) MI300X and MI355X accelerators.",'v6.1 Dell_MangoBoost heterogeneous entry','32 GPUs, MI300X and MI355X',f'{hc["total_accelerators"]} accelerators, system name {hc["SystemName"][:70]}','CONSISTENT' if hc['total_accelerators']==32 else 'BELOW',''))
O.append(mk('O10','The configuration delivered 253,501 tokens/s on GPT-OSS-120B Server and 285,454 tokens/s Offline','same entry, GPT-OSS-120B','253,501 and 285,454',f'{b("Dell_MangoBoost","Four-Cluster","gpt-oss-120b","Server"):,.0f} and {b("Dell_MangoBoost","Four-Cluster","gpt-oss-120b","Offline"):,.0f}','CONSISTENT' if round(b("Dell_MangoBoost","Four-Cluster","gpt-oss-120b","Server"))==253501 and round(b("Dell_MangoBoost","Four-Cluster","gpt-oss-120b","Offline"))==285454 else 'ABOVE',''))
# ---- post 3, YOLO v6.0
E=[x for x in A if 'yolo' in x['Model'] and x['Category']=='closed']
def y(i,s,m='yolo-95'): r=[x for x in E if x['ID']==i and x['Model']==m and x['Scenario']==s]; assert len(r)==1; return r[0]['Performance_Result']
Y=[]
Y.append(mk('Y1','The published v6.0 result for the Dell Pro Max with GB10 on yolo-95 and yolo-99 Offline shows 1.75 samples per second.','entry 6.0-0028, YOLO Offline, both models','1.75 samples/s',f'yolo-95 {y("6.0-0028","Offline"):.5f}, yolo-99 {y("6.0-0028","Offline","yolo-99"):.5f} samples/s','CONSISTENT' if abs(y("6.0-0028","Offline")-1.75)<0.005 else 'ABOVE',''))
sub=sorted({x['Submitter'] for x in E})
Y.append(mk('Y2','Dell was one of two organizations to submit YOLO results for the edge suite: the other was GATEOverflow','closed edge YOLO entries in v6.0','two organizations','Submitters: '+', '.join(sub),'CONSISTENT' if sub==['Dell','GATEOverflow'] else 'BELOW',''))
tb=[('6.0-0028',1.75,611.93,4891.38),('6.0-0030',102.23,10.55,81.09),('6.0-0029',153.54,7.12,54.67),('6.0-0036',12.07,90.11,843.37),('6.0-0034',24.19,43.15,344.44)]
okt=all(abs(y(i,'Offline')-o)<0.006 and abs(y(i,'SingleStream')-s)<0.006 and abs(y(i,'MultiStream')-m)<0.006 for i,o,s,m in tb)
Y.append(mk('Y3','Table 1: Summary of the YOLOv11 results. Dell Pro Max (CPU only) GB10 x1 Offline 1.75, SingleStream 611.93, MultiStream 4,891.38','entries 6.0-0028, 6.0-0030, 6.0-0029, 6.0-0036 and 6.0-0034, YOLO Offline, SingleStream and MultiStream','fifteen published values','; '.join(f'{i}: {y(i,"Offline"):.2f}, {y(i,"SingleStream"):.2f}, {y(i,"MultiStream"):.2f}' for i,_,_,_ in tb),'CONSISTENT' if okt else 'ABOVE','The corrected GB10 row in the same table is not in the file.'))
Y.append(mk('Y4','roughly 10x ahead of the L4 at 6.39 samples per second and roughly 3.4x ahead of the L40S at 19.19 samples per second','entries 6.0-0030 (16 x L4) and 6.0-0029 (8 x L40S), YOLO Offline divided by the GPU count','6.39 and 19.19 per GPU',f'{y("6.0-0030","Offline")/16:.2f} and {y("6.0-0029","Offline")/8:.2f} per GPU','CONSISTENT' if abs(y("6.0-0030","Offline")/16-6.39)<0.006 and abs(y("6.0-0029","Offline")/8-19.19)<0.006 else 'ABOVE','The 10x and 3.4x ratios use the corrected GB10 value, which is not in the file.'))
Y.append(mk('Y5','the corrected Offline throughput for the Dell Pro Max with GB10 on both yolo-95 and yolo-99 is: 64.07028 samples per second. This is a ~37x improvement over the published CPU result of 1.75 samples per second','Dell Pro Max GB10 entries in the v6.0 file, and the later v6.1 file','64.07028 samples/s, about 37x',f'v6.0 file: {y("6.0-0028","Offline"):.2f} samples/s. The post gives the corrected run as not official. The v6.1 file lists Dell Pro Max (1x GB10) YOLO Offline at {b("Dell","Dell Pro Max","yolo-95","offline"):.4f} samples/s','CANNOT_TELL',f'The post prints 64.07028 and also 64.7028. Over 1.75 they give {64.07028/1.75:.1f}x and {64.7028/1.75:.1f}x. The corrected run is not in any MLCommons file.'))
Y.append(mk('Y6','The table above shows a significant and expected drop in latency when running on the GPU, nearly 51x in the SingleStream and MultiStream scenarios.','published GB10 latencies (entry 6.0-0028) over the corrected latencies in the post table (12.02 ms and 94.52 ms)','nearly 51x',f'Published {y("6.0-0028","SingleStream"):.2f} ms and {y("6.0-0028","MultiStream"):.2f} ms. Over the corrected values: {y("6.0-0028","SingleStream")/12.02:.1f}x and {y("6.0-0028","MultiStream")/94.52:.1f}x. The v6.1 file lists {b("Dell","Dell Pro Max","yolo-95","singlestream"):.2f} ms and {b("Dell","Dell Pro Max","yolo-95","multistream"):.2f} ms','CANNOT_TELL','The corrected latencies are not official numbers.'))
Y.append(mk('Y7','Table 1: Summary of the YOLOv11 results. Dell Pro Max 64.70, 12.02, 94.52, 0.462. GATEOverflow Lenovo IdeaPad Gaming 3 15ARH05 NVIDIA GeForce GTX 1650 Ti 24.19, 43.15, 344.44, 5 W, 0.484.','spec power and efficiency columns of the table, entry 6.0-0034 (GTX 1650 Ti) Offline 24.187','5 W and 0.484 samples/s/W',f'The v6.0 file has no power for these entries. 24.187 over 5 W is {24.187/5:.2f}. 24.187 over 0.484 is {24.187/0.484:.0f} W. The post text gives the card as 80 W','CANNOT_TELL','The efficiency column for this row does not follow from the 5 W in the same row.'))
for nm,L,srcs in (('claims_dell_mi355x_v60.json',M,['raw/inf_6.0.json']),('claims_dell_overview_v61.json',O,['raw/inf_6.0.json','raw/inf_6.1.json']),('claims_dell_yolo_v60.json',Y,['raw/inf_6.0.json'])):
    json.dump(dict(source=srcs,sha256=[hashlib.sha256(open(s,'rb').read()).hexdigest() for s in srcs],claims=L),open(nm,'w'),indent=1)
    for c in L: print(c['id'],c['outcome'],'|',c['stated'],'|',c['delivered'][:200])
